  (VELAPOKA_INSPECT_WIDTH * VELAPOKA_INSPECT_HEIGHT)

#define VELAPOKA_ROI_X               48
#define VELAPOKA_ROI_Y               32
#define VELAPOKA_ROI_WIDTH           224
