#define VELAPOKA_BLOCK_COLUMNS \
  (VELAPOKA_ROI_WIDTH / VELAPOKA_INSPECT_BLOCK_SIZE)
#define VELAPOKA_BLOCK_ROWS \
  (VELAPOKA_ROI_HEIGHT / VELAPOKA_INSPECT_BLOCK_SIZE)
