+  while (received < size)
+    {
+      ssize_t ret = read(fd, buffer + received, size - received);
+
+      if (ret < 0)
+        {
+          if (errno == EINTR)
+            {
+              continue;
+            }
+
+          return -errno;
+        }
+
+      if (ret == 0)
+        {
+          return -EIO;
+        }
+
+      received += ret;
+    }
+
+  return OK;
+}
