+  char path[VELAPOKA_STORAGE_PATH_SIZE];
+  uint32_t image_size = VELAPOKA_INSPECT_SIZE;
+  uint32_t file_size = VELAPOKA_BMP_HEADER_SIZE + image_size;
+  unsigned int i;
+  int length;
+  int fd;
