 *
 ****************************************************************************/

struct spi_dev_s *esp_spi_bitbang_init(void)
{
  /* Configure the SPI bit-bang pins */

  /* A bit-banged controller always drives chip select in software.  Do not
   * make CS pin setup depend on ESPRESSIF_SPI_SWCS: that option belongs to
   * the hardware SPI peripheral and is normally disabled for a bitbang-only
   * configuration.
   */

  /* Do not request FUNCTION_1 here.  esp_configgpio() translates that
   * encoding to IOMUX function 0, which is the native SDMMC function on
   * ESP32-P4 GPIO39..44.  With no FUNCTION bits, PIN_FUNC_GPIO is selected
   * and esp_gpiowrite()/esp_gpioread() actually control the pads.
   */

  esp_configgpio(CONFIG_ESPRESSIF_SPI_BITBANG_CSPIN,
                 INPUT | OUTPUT | PULLUP);
  esp_configgpio(CONFIG_ESPRESSIF_SPI_BITBANG_MOSIPIN,
                 INPUT | OUTPUT | PULLUP);
  esp_configgpio(CONFIG_ESPRESSIF_SPI_BITBANG_MISOPIN,
                 INPUT | PULLUP);
  esp_configgpio(CONFIG_ESPRESSIF_SPI_BITBANG_CLKPIN,
                 INPUT | OUTPUT);

  /* GPIO function/matrix configuration can reset the output latch.  Apply
   * the inactive bus levels only after all pins have been configured.  An SD
   * card needs CS and MOSI high while receiving the initial clocks before
   * CMD0 selects SPI mode.
   */

  esp_gpiowrite(CONFIG_ESPRESSIF_SPI_BITBANG_CSPIN, true);
  esp_gpiowrite(CONFIG_ESPRESSIF_SPI_BITBANG_MOSIPIN, true);
  esp_gpiowrite(CONFIG_ESPRESSIF_SPI_BITBANG_CLKPIN, false);

  /* Create the SPI driver instance */

  return spi_create_bitbang(&esp_spi_bitbang_ops, NULL);
}

