static int capture_unlink(FAR struct inode *inode)
{
  FAR capture_mng_t *cmng = inode->i_private;

  if (cmng == NULL)
    {
      return -EINVAL;
    }

  nxmutex_lock(&cmng->mutex);
  if (cmng->open_num == 0)
    {
      nxmutex_unlock(&cmng->mutex);
      nxmutex_destroy(&cmng->mutex);
      kmm_free(cmng);
      inode->i_private = NULL;
    }
  else
    {
      cmng->unlinked = true;
      nxmutex_unlock(&cmng->mutex);
    }

  return OK;
}
