static uint32_t velapoka_crc32(FAR const uint8_t *data, size_t size)
{
  uint32_t crc = UINT32_MAX;
  size_t i;

  for (i = 0; i < size; i++)
    {
      unsigned int bit;

      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc >> 1) ^
                (UINT32_C(0xedb88320) & (0 - (crc & 1)));
        }
    }

  return ~crc;
}

