static int velapoka_write_all(int fd, FAR const uint8_t *buffer,
                              size_t size)
{
  size_t written = 0;

  while (written < size)
    {
      ssize_t ret = write(fd, buffer + written, size - written);

      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (ret == 0)
        {
          return -EIO;
        }

      written += ret;
    }

  return OK;
}

static int velapoka_read_all(int fd, FAR uint8_t *buffer, size_t size)
{
  size_t received = 0;

  while (received < size)
    {
      ssize_t ret = read(fd, buffer + received, size - received);

      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (ret == 0)
        {
          return -EIO;
        }

      received += ret;
    }

  return OK;
}

