{
  char partial[VELAPOKA_STORAGE_PATH_SIZE];
  FAR char *separator;
  size_t length;
  int ret;

  length = strlen(path);
  if (length == 0 || length >= sizeof(partial) || path[0] != '/')
    {
      return -EINVAL;
    }

  memcpy(partial, path, length + 1);
  separator = partial + 1;
  while ((separator = strchr(separator, '/')) != NULL)
    {
      *separator = '\0';
      ret = velapoka_mkdir(partial);
      *separator = '/';
      if (ret < 0)
        {
          return ret;
        }

      separator++;
    }

  return velapoka_mkdir(partial);
}

