+  for (i = 0; i < VELAPOKA_STORAGE_QUEUE_DEPTH; i++)
+    {
+      free(storage->requests[i].image);
+    }
+
+  free(storage->reference);
+  pthread_cond_destroy(&storage->cond);
+  pthread_mutex_destroy(&storage->lock);
+  free(storage);
+}
