    (storage->request_tail + 1) % VELAPOKA_STORAGE_QUEUE_DEPTH;
  storage->request_count++;
  pthread_cond_signal(&storage->cond);
  pthread_mutex_unlock(&storage->lock);
  *record_id = id;
  return OK;
}

