   652	int velapoka_camera_initialize(void)
   653	{
   654	  const esp_ldo_channel_config_t ldo_cfg =
   655	  {
   656	    .chan_id = BOARD_VELAPOKA_CSI_LDO_CHANNEL,
   657	    .voltage_mv = BOARD_VELAPOKA_CSI_LDO_MV,
   658	  };
   659	  FAR struct i2c_master_s *i2c;
   660	  uint16_t pid;
   660	  uint16_t pid;
   661	  uint8_t idh;
   662	  uint8_t idl;
   663	  int ret;
   664	
   665	  i2c = velapoka_i2c_initialize();
   666	  if (i2c == NULL)
   667	    {
   668	      return -ENODEV;
   669	    }
   670	
   671	  ret = sc2336_readreg(i2c, SC2336_REG_CHIP_ID_H, &idh);
   672	  if (ret < 0)
   673	    {
   674	      syslog(LOG_ERR, "ERROR: SC2336 PID high read failed: %d\n", ret);
   675	      return ret;
   676	    }
   677	
   678	  ret = sc2336_readreg(i2c, SC2336_REG_CHIP_ID_L, &idl);
   679	  if (ret < 0)
   680	    {
   681	      syslog(LOG_ERR, "ERROR: SC2336 PID low read failed: %d\n", ret);
   682	      return ret;
   683	    }
   684	
   685	  pid = ((uint16_t)idh << 8) | idl;
   686	  if (pid != BOARD_VELAPOKA_CAMERA_PID)
   687	    {
   688	      syslog(LOG_ERR,
   689	             "ERROR: camera at 0x%02x has PID 0x%04x, expected 0x%04x\n",
   690	             BOARD_VELAPOKA_CAMERA_ADDR, pid,
   691	             BOARD_VELAPOKA_CAMERA_PID);
   692	      return -ENODEV;
   693	    }
   694	
   695	  /* ESP32-P4 CSI D-PHY requires a stable 2.5 V supply.  Keep an explicit
   696	   * camera-side reference even when the board's DSI display uses the same
   697	   * LDO channel.  The regulator driver shares non-adjustable consumers by
   698	   * reference count, matching esp-video's CSI device initialization.
   699	   */
   700	
   701	  ret = esp_ldo_acquire_channel(&ldo_cfg, &g_csi_ldo);
   702	  if (ret != ESP_OK)
   703	    {
   704	      syslog(LOG_ERR, "ERROR: SC2336 CSI LDO%d %dmV acquisition failed: %d\n",
   705	             BOARD_VELAPOKA_CSI_LDO_CHANNEL,
   706	             BOARD_VELAPOKA_CSI_LDO_MV, ret);
   707	      return -EIO;
   708	    }
   709	
   710	  nxsig_usleep(1000);
   711	  syslog(LOG_INFO, "SC2336 CSI: LDO%d=%dmV enabled\n",
   712	         BOARD_VELAPOKA_CSI_LDO_CHANNEL, BOARD_VELAPOKA_CSI_LDO_MV);
   713	
   714	  ret = sc2336_write_mode(i2c);
   715	  if (ret < 0)
   716	    {
   717	      return ret;
   718	    }
   719	
   720	  /* Keep the sensor in standby.  The CSI/V4L2 lower half starts the sensor
   721	   * only after a capture buffer and the receiver are both ready.
   722	   */
   723	
   724	  ret = sc2336_writereg(i2c, SC2336_REG_STREAM, 0x00);
   725	  if (ret < 0)
   726	    {
   727	      return ret;
   728	    }
   729	
   730	  g_sc2336_i2c = i2c;
   731	
   732	  g_sc2336.sensor.ops              = &g_sc2336_sensor_ops;
   733	  g_sc2336.sensor.fmtdescs_num     = 1;
   734	  g_sc2336.sensor.fmtdescs         = g_sc2336_fmtdesc;
   735	  g_sc2336.sensor.frmsizes_num     = 1;
   736	  g_sc2336.sensor.frmsizes         = g_sc2336_frmsize;
   737	  g_sc2336.sensor.frmintervals_num = 1;
   738	  g_sc2336.sensor.frmintervals     = g_sc2336_frmival;
   739	  g_sc2336.data.ops                = &g_sc2336_data_ops;
   740	
   741	  /* Reserve and configure CSI before the display creates its DW-GDMA
   742	   * channel.  CSI and DPI share the same DW-GDMA group: the first channel
   743	   * creation resets that group, while later channels only add their own
   744	   * register state.  Initializing CSI lazily after DPI can therefore leave
   745	   * its CSI-handshake channel unable to drain the bridge FIFO (the bridge
