   757	    }
   758	
   759	  {
   760	    FAR struct imgsensor_s *sensors[1] = {&g_sc2336.sensor};
   761	
   762	    ret = capture_register("/dev/video0", &g_sc2336.data, sensors, 1);
   763	    if (ret < 0)
   764	      {
   765	        syslog(LOG_ERR, "ERROR: SC2336 /dev/video0 register failed: %d\n",
   766	               ret);
   767	        return ret;
   768	      }
   769	  }
   770	
   771	  syslog(LOG_INFO,
   772	         "SC2336: PID=0x%04x addr=0x%02x mode=%ux%u RAW%u %ufps "
   773	         "%u-lane initialized (standby), /dev/video0 registered\n",
   774	         pid, BOARD_VELAPOKA_CAMERA_ADDR,
   775	         BOARD_VELAPOKA_CAMERA_WIDTH, BOARD_VELAPOKA_CAMERA_HEIGHT,
   776	         BOARD_VELAPOKA_CAMERA_RAW_BITS, BOARD_VELAPOKA_CAMERA_FPS,
   777	         BOARD_VELAPOKA_CAMERA_CSI_LANES);
   778	  return OK;
   779	}
