   781	int velapoka_camera_set_stream(bool enable)
   782	{
   783	  uint8_t stream;
   784	  unsigned int attempt;
   785	  int ret;
   786	
   787	  if (g_sc2336_i2c == NULL)
   788	    {
   789	      return -ENODEV;
   790	    }
   791	
   792	  /* The sensor needs a short settling interval after 0x0100 changes state.
   793	   * Do not sample the register immediately while the MIPI receiver is also
   794	   * being armed: a failed SCCB read previously made capture continue with an
   795	   * unverified stream state, which leaves CSI waiting forever for a frame. */
   796	
   797	  for (attempt = 0; attempt < 3; attempt++)
   798	    {
   799	      ret = sc2336_writereg(g_sc2336_i2c, SC2336_REG_STREAM,
   800	                            enable ? 0x01 : 0x00);
   801	      if (ret < 0)
   802	        {
   803	          continue;
   804	        }
   805	
   806	      nxsig_usleep(5000);
   807	      ret = sc2336_readreg(g_sc2336_i2c, SC2336_REG_STREAM, &stream);
   808	      if (ret == OK && stream == (enable ? 0x01 : 0x00))
   809	        {
   810	          syslog(LOG_INFO, "SC2336: stream %s, reg 0x0100=0x%02x\n",
   811	                 enable ? "on" : "off", stream);
   812	          return OK;
   813	        }
   814	    }
   815	
   816	  if (ret < 0)
   817	    {
   818	      syslog(LOG_ERR, "ERROR: SC2336 stream %s readback failed: %d\n",
   819	             enable ? "on" : "off", ret);
   820	      return ret;
   821	    }
   822	
   823	  syslog(LOG_ERR, "ERROR: SC2336 stream %s readback=0x%02x\n",
   824	         enable ? "on" : "off", stream);
   825	  return -EIO;
   826	}

