   159	      for (x = 0; x < VELAPOKA_CAMERA_PREVIEW_WIDTH; x++)
   160	        {
   161	          unsigned int sx = x * VELAPOKA_CAMERA_WIDTH /
   162	                            VELAPOKA_CAMERA_PREVIEW_WIDTH;
   163	          unsigned int value = src[(sx / 4) * 5 + sx % 4] *
   164	                               CONFIG_EXAMPLES_VELAPOKA_PREVIEW_GAIN;
