   231	      velapoka_set_state(&state, VELAPOKA_STATE_READY);
   232	      velapoka_ui_set_message("TEMPLATE RESTORED",
   233	                              "Reference and threshold loaded from SD",
   234	                              false);
   235	    }
   236	
   237	  while (!g_velapoka_exit_requested)
   238	    {
   239	      enum velapoka_ui_action_e action;
   240	      uint32_t idle;
   241	
   242	      action = velapoka_ui_take_action();
   243	      if (action == VELAPOKA_UI_ACTION_ENROLL)
   244	        {
   245	          if (camera == NULL || inspector == NULL)
   246	            {
   247	              velapoka_set_state(&state, VELAPOKA_STATE_ERROR);
   248	              velapoka_ui_set_message("ENROLL ERROR",
   249	                                      "Camera or inspector is offline",
   250	                                      true);
   251	            }
   252	          else
   253	            {
   254	              ret = velapoka_inspect_enroll_begin(inspector);
   255	              if (ret == OK)
   256	                {
   257	                  velapoka_set_state(&state,
   258	                                     VELAPOKA_STATE_SAMPLE_CAPTURE);
   259	                  velapoka_ui_clear_boxes();
   260	                  velapoka_ui_set_enroll_progress(0, 3);
   260	                  velapoka_ui_set_enroll_progress(0, 3);
   261	                }
   262	              else
   263	                {
   264	                  velapoka_ui_set_message("ENROLL BUSY",
   265	                                          "Wait for inspection to finish",
   266	                                          true);
   267	                }
   268	            }
   269	        }
   270	      else if (action == VELAPOKA_UI_ACTION_INSPECT)
   271	        {
   272	          if (camera == NULL || inspector == NULL ||
   273	              !velapoka_inspect_reference_ready(inspector))
   274	            {
   275	              velapoka_set_state(&state, VELAPOKA_STATE_ERROR);
   276	              velapoka_ui_set_message("NO REFERENCE",
   277	                                      "Enroll a standard sample first",
   278	                                      true);
   279	            }
   280	          else if (state.current == VELAPOKA_STATE_INSPECT ||
   281	                   state.current == VELAPOKA_STATE_PREPROCESS ||
   282	                   state.current == VELAPOKA_STATE_CAPTURE)
   283	            {
   284	              velapoka_ui_set_message("INSPECT BUSY",
   285	                                      "Current inspection is running",
   286	                                      false);
   287	            }
   288	          else
   289	            {
   290	              if (state.current == VELAPOKA_STATE_IDLE ||
   291	                  state.current == VELAPOKA_STATE_ERROR)
   292	                {
   293	                  velapoka_set_state(&state, VELAPOKA_STATE_READY);
   294	                }
   295	
   296	              velapoka_set_state(&state, VELAPOKA_STATE_CAPTURE);
   297	              velapoka_ui_clear_boxes();
   298	              velapoka_ui_set_message("CAPTURE",
   299	                                      "Waiting for the next camera frame",
   300	                                      false);
   301	            }
   302	        }
   303	      else if (action == VELAPOKA_UI_ACTION_STOP)
   304	        {
   305	          velapoka_inspect_discard_result(inspector);
   306	          velapoka_set_state(&state, VELAPOKA_STATE_IDLE);
   307	          velapoka_ui_clear_boxes();
   308	          velapoka_ui_set_message("STOPPED",
   309	                                  "Enroll or inspect when ready", false);
   310	        }
   311	      else if (action == VELAPOKA_UI_ACTION_EXIT)
   312	        {
   313	          velapoka_ui_set_message("SHUTTING DOWN",
   314	                                  "Flushing storage and unmounting SD",
   315	                                  false);
   316	          lv_timer_handler();
