   318	        }
   319	
   320	      if (camera != NULL)
   321	        {
   322	          struct velapoka_camera_frame_s frame;
   323	
   324	          ret = velapoka_camera_acquire(camera, &frame);
   325	          if (ret > 0)
   326	            {
   327	              ret = velapoka_ui_update_preview(frame.data, frame.size,
   328	                                               frame.sequence);
   329	              if (ret == OK && state.current ==
   330	                               VELAPOKA_STATE_SAMPLE_CAPTURE)
   331	                {
   332	                  unsigned int captured;
   333	                  bool ready;
   334	
   335	                  ret = velapoka_inspect_enroll_frame(inspector,
   336	                                                       frame.data,
   337	                                                       frame.size,
   338	                                                       &captured, &ready);
   339	                  if (ret == OK)
   340	                    {
   341	                      velapoka_ui_set_enroll_progress(captured, 3);
   342	                      if (ready)
   343	                        {
   344	                          velapoka_set_state(&state,
   345	                                             VELAPOKA_STATE_SAVE_SAMPLE);
   346	                          if (storage != NULL && storage_image != NULL)
   347	                            {
   348	                              ret = velapoka_inspect_reference_export(
   349	                                inspector, storage_image,
   350	                                VELAPOKA_INSPECT_SIZE);
   351	                              if (ret == OK)
   352	                                {
   353	                                  ret = velapoka_storage_save_reference(
   354	                                    storage, storage_image,
   355	                                    VELAPOKA_INSPECT_SIZE,
   356	                                    velapoka_ui_get_threshold());
   357	                                }
   358	                            }
   359	                          else
   360	                            {
   361	                              ret = -ENODEV;
   362	                            }
   363	
   364	                          if (ret == OK)
   365	                            {
   366	                              velapoka_ui_set_message(
   367	                                "SAMPLE READY",
   368	                                "Reference queued for SD storage", false);
   369	                            }
   370	                          else
   371	                            {
   372	                              fprintf(stderr,
   373	                                      "velapoka: template save failed: %d\n",
   374	                                      ret);
   375	                              velapoka_ui_set_message(
   376	                                "SAMPLE READY",
   377	                                "Reference active; SD save failed", true);
   378	                            }
   379	
   380	                          velapoka_set_state(&state,
   381	                                             VELAPOKA_STATE_READY);
   382	                        }
   383	                    }
   384	                  else
   385	                    {
   386	                      velapoka_set_state(&state, VELAPOKA_STATE_ERROR);
   387	                      velapoka_ui_set_message("ENROLL ERROR",
   388	                                              "Reference capture failed",
   389	                                              true);
   390	                    }
   391	                }
   392	              else if (ret == OK &&
   393	                       state.current == VELAPOKA_STATE_CAPTURE)
   394	                {
   395	                  velapoka_set_state(&state,
   396	                                     VELAPOKA_STATE_PREPROCESS);
   397	                  ret = velapoka_inspect_submit(
   398	                    inspector, frame.data, frame.size, frame.sequence,
   399	                    velapoka_ui_get_threshold());
   400	                  if (ret == OK)
   401	                    {
   402	                      velapoka_set_state(&state,
   403	                                         VELAPOKA_STATE_INSPECT);
   404	                      velapoka_ui_set_message("INSPECTING",
   405	                                              "P0 comparison is running",
   406	                                              false);
   407	                    }
   408	                  else
   409	                    {
   410	                      velapoka_set_state(&state, VELAPOKA_STATE_ERROR);
