   412	                                              "Could not queue the frame",
   413	                                              true);
   414	                    }
   415	                }
   416	
   417	              velapoka_camera_release(camera, &frame);
   418	              if (ret < 0)
   419	                {
   420	                  fprintf(stderr, "velapoka: preview update failed: %d\n",
   421	                          ret);
   422	                }
   423	            }
   424	          else if (ret < 0)
   425	            {
   426	              fprintf(stderr, "velapoka: camera offline: %d\n", ret);
   427	              velapoka_ui_set_camera_online(false);
   428	              velapoka_camera_stop(camera);
   429	              camera = NULL;
   430	            }
   431	        }
   432	
   433	      if (inspector != NULL)
   434	        {
   435	          struct velapoka_result_s inspection;
   436	
   437	          ret = velapoka_inspect_poll(inspector, &inspection);
   438	          if (ret > 0 && state.current == VELAPOKA_STATE_INSPECT)
   439	            {
   440	              uint32_t record_id;
   441	
   442	              velapoka_set_state(&state,
   443	                                 inspection.pass ? VELAPOKA_STATE_PASS :
   444	                                                   VELAPOKA_STATE_FAIL);
