   449	                     inspection.pass ? "PASS" : "FAIL",
   450	                     inspection.score_tenths / 10,
   451	                     inspection.score_tenths % 10,
   452	                     inspection.difference_tenths / 10,
   453	                     inspection.difference_tenths % 10,
   454	                     inspection.box_count, inspection.elapsed_ms,
   455	                     inspection.sequence);
   456	
   457	              if (storage != NULL)
   458	                {
   459	                  if (!inspection.pass)
   460	                    {
   461	                      ret = velapoka_inspect_snapshot(
   462	                        inspector, storage_image, VELAPOKA_INSPECT_SIZE);
   463	                    }
   464	                  else
   465	                    {
   466	                      ret = OK;
   467	                    }
   468	
   469	                  if (ret == OK)
   470	                    {
   471	                      ret = velapoka_storage_save_result(
   472	                        storage, &inspection,
   473	                        inspection.pass ? NULL : storage_image,
   474	                        inspection.pass ? 0 : VELAPOKA_INSPECT_SIZE,
   475	                        velapoka_ui_get_threshold(), &record_id);
   476	                    }
   477	
   478	                  if (ret == OK)
   479	                    {
   480	                      history_count = velapoka_storage_get_history(
   481	                        storage, history, VELAPOKA_HISTORY_COUNT);
   482	                      velapoka_ui_set_history(history, history_count);
   483	                      printf("velapoka: result queued as record #%" PRIu32
   484	                             "\n", record_id);
   485	                    }
   486	                  else
   487	                    {
   488	                      fprintf(stderr,
   489	                              "velapoka: result storage failed: %d\n", ret);
   490	                    }
   491	                }
   492	
   493	              velapoka_set_state(&state, VELAPOKA_STATE_SAVE_RESULT);
   494	              velapoka_set_state(&state, VELAPOKA_STATE_READY);
   495	            }
   496	        }
   497	
   498	      storage_online = velapoka_storage_online(storage);
   499	      if (storage_online != previous_storage_online)
   500	        {
   501	          velapoka_ui_set_storage_online(storage_online);
   502	          previous_storage_online = storage_online;
   503	          if (!storage_online)
   504	            {
   505	              fprintf(stderr, "velapoka: storage went offline: %d\n",
   506	                      velapoka_storage_last_error(storage));
   507	            }
   508	        }
   509	
   510	      if (sync_fd >= 0)
   511	        {
   512	          do
   513	            {
   514	              ret = ioctl(sync_fd, FBIO_WAITFORVSYNC, 0);
   515	            }
   516	          while (ret < 0 && errno == EINTR &&
   517	                 !g_velapoka_exit_requested);
   518	
   519	          if (ret < 0 &&
   520	              !(errno == EINTR && g_velapoka_exit_requested))
   521	            {
   522	              fprintf(stderr, "velapoka: VSYNC wait failed: %d\n", errno);
   523	              close(sync_fd);
   524	              sync_fd = -1;
   525	            }
   526	        }
   527	
   528	      idle = lv_timer_handler();
   529	
   530	      if (sync_fd >= 0)
   531	        {
   532	          idle = 1;
   533	        }
   534	      else if (idle < 1)
   535	        {
   536	          idle = 1;
   537	        }
   538	      else if (idle > 20)
   539	        {
   540	          idle = 20;
   541	        }
   542	
   543	      usleep(idle * 1000);
   544	    }
