   554	                              "Storage flush failed; keep SD inserted",
   555	                              true);
   556	    }
   557	  else
   558	    {
   559	      velapoka_ui_set_message("SAFE EXIT COMPLETE",
   560	                              "Storage saved; safe to power off",
   561	                              false);
   562	    }
   563	
   564	  lv_timer_handler();
   565	  usleep(200 * 1000);
   566	
   567	  if (sync_fd >= 0)
   568	    {
   569	      close(sync_fd);
   570	    }
   571	
   572	  free(storage_image);
   573	  lv_nuttx_deinit(&result);
   574	  lv_deinit();
