   128	static void velapoka_find_components(
   129	  FAR const bool *abnormal, FAR struct velapoka_result_s *result,
   130	  FAR unsigned int *largest_blocks)
   131	{
   132	  struct velapoka_component_s components[VELAPOKA_BLOCK_COUNT];
   133	  bool visited[VELAPOKA_BLOCK_COUNT];
   134	  uint8_t queue[VELAPOKA_BLOCK_COUNT];
   135	  unsigned int component_count = 0;
   136	  unsigned int index;
   137	
   138	  memset(visited, 0, sizeof(visited));
   139	  *largest_blocks = 0;
   140	
   141	  for (index = 0; index < VELAPOKA_BLOCK_COUNT; index++)
   142	    {
   143	      struct velapoka_component_s component;
   144	      unsigned int head;
   145	      unsigned int tail;
