   154	      component.blocks = 0;
   155	      head = 0;
   156	      tail = 0;
   157	      queue[tail++] = index;
   158	      visited[index] = true;
   159	
   160	      while (head < tail)
   161	        {
   162	          unsigned int current = queue[head++];
   163	          unsigned int block_x = current % VELAPOKA_BLOCK_COLUMNS;
   164	          unsigned int block_y = current / VELAPOKA_BLOCK_COLUMNS;
   165	          int dx;
   166	          int dy;
   167	
   168	          component.blocks++;
   169	          if (block_x < component.min_x)
   170	            {
   171	              component.min_x = block_x;
   172	            }
   173	
   174	          if (block_x > component.max_x)
   175	            {
   176	              component.max_x = block_x;
   177	            }
   178	
   179	          if (block_y < component.min_y)
   180	            {
   181	              component.min_y = block_y;
   182	            }
   183	
   184	          if (block_y > component.max_y)
   185	            {
   186	              component.max_y = block_y;
   187	            }
   188	
   189	          for (dy = -1; dy <= 1; dy++)
   190	            {
   191	              for (dx = -1; dx <= 1; dx++)
   192	                {
   193	                  int neighbor_x = (int)block_x + dx;
