   371	static FAR void *velapoka_inspect_thread(FAR void *arg)
   372	{
   373	  FAR struct velapoka_inspector_s *inspector = arg;
   374	
   375	  for (; ; )
   376	    {
   377	      struct velapoka_result_s result;
   378	
   379	      pthread_mutex_lock(&inspector->lock);
   380	      while (!inspector->pending && !inspector->stop)
   381	        {
   382	          pthread_cond_wait(&inspector->cond, &inspector->lock);
   383	        }
   384	
   385	      if (inspector->stop)
   386	        {
   387	          pthread_mutex_unlock(&inspector->lock);
   388	          break;
   389	        }
   390	
   391	      inspector->pending = false;
   392	      pthread_mutex_unlock(&inspector->lock);
