   396	      pthread_mutex_lock(&inspector->lock);
   397	      inspector->result = result;
   398	      inspector->result_ready = true;
   399	      inspector->busy = false;
   400	      pthread_mutex_unlock(&inspector->lock);
   401	    }
   402	
   403	  return NULL;
   404	}
