    96	static void velapoka_put_le16(FAR uint8_t *buffer, uint16_t value)
    97	{
    98	  buffer[0] = value & 0xff;
    99	  buffer[1] = value >> 8;
   100	}
   101	
   102	static void velapoka_put_le32(FAR uint8_t *buffer, uint32_t value)
   103	{
   104	  buffer[0] = value & 0xff;
   105	  buffer[1] = (value >> 8) & 0xff;
   106	  buffer[2] = (value >> 16) & 0xff;
   107	  buffer[3] = value >> 24;
   108	}
   109	
   110	static uint16_t velapoka_get_le16(FAR const uint8_t *buffer)
   111	{
   112	  return (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
   113	}
   114	
   115	static uint32_t velapoka_get_le32(FAR const uint8_t *buffer)
   116	{
   117	  return (uint32_t)buffer[0] | ((uint32_t)buffer[1] << 8) |
   118	         ((uint32_t)buffer[2] << 16) | ((uint32_t)buffer[3] << 24);
   119	}
