   121	static uint32_t velapoka_crc32(FAR const uint8_t *data, size_t size)
   122	{
   123	  uint32_t crc = UINT32_MAX;
   124	  size_t i;
   125	
   126	  for (i = 0; i < size; i++)
   127	    {
   128	      unsigned int bit;
   129	
   130	      crc ^= data[i];
   131	      for (bit = 0; bit < 8; bit++)
   132	        {
   133	          crc = (crc >> 1) ^
   134	                (UINT32_C(0xedb88320) & (0 - (crc & 1)));
   135	        }
   136	    }
   137	
   138	  return ~crc;
   139	}
