   152	static int velapoka_write_all(int fd, FAR const uint8_t *buffer,
   153	                              size_t size)
   154	{
   155	  size_t written = 0;
   156	
   157	  while (written < size)
   158	    {
   159	      ssize_t ret = write(fd, buffer + written, size - written);
   160	
   161	      if (ret < 0)
   162	        {
   163	          if (errno == EINTR)
   164	            {
   165	              continue;
   166	            }
   167	
   168	          return -errno;
   169	        }
   170	
   171	      if (ret == 0)
   172	        {
   173	          return -EIO;
   174	        }
   175	
   176	      written += ret;
   177	    }
   178	
   179	  return OK;
   180	}
