   560	static int velapoka_storage_write_reference(
   561	  FAR const uint8_t *reference, unsigned int threshold_percent)
   562	{
   563	  uint8_t header[VELAPOKA_STORAGE_HEADER_SIZE];
   564	  char temporary[VELAPOKA_STORAGE_PATH_SIZE];
   565	  char destination[VELAPOKA_STORAGE_PATH_SIZE];
   566	  int fd;
   567	  int ret;
   568	
   569	  memset(header, 0, sizeof(header));
   570	  velapoka_put_le32(&header[0], VELAPOKA_STORAGE_MAGIC);
   571	  velapoka_put_le16(&header[4], VELAPOKA_STORAGE_VERSION);
   572	  velapoka_put_le16(&header[6], VELAPOKA_STORAGE_HEADER_SIZE);
   573	  velapoka_put_le16(&header[8], VELAPOKA_INSPECT_WIDTH);
   574	  velapoka_put_le16(&header[10], VELAPOKA_INSPECT_HEIGHT);
   575	  velapoka_put_le16(&header[12], VELAPOKA_ROI_X);
   576	  velapoka_put_le16(&header[14], VELAPOKA_ROI_Y);
   577	  velapoka_put_le16(&header[16], VELAPOKA_ROI_WIDTH);
   578	  velapoka_put_le16(&header[18], VELAPOKA_ROI_HEIGHT);
   579	  velapoka_put_le16(&header[20], threshold_percent);
   580	  velapoka_put_le32(&header[24], VELAPOKA_INSPECT_SIZE);
   581	  velapoka_put_le32(&header[28],
   582	                    velapoka_crc32(reference, VELAPOKA_INSPECT_SIZE));
   583	
   584	  ret = velapoka_path(temporary, sizeof(temporary),
   585	                      VELAPOKA_STORAGE_TEMPLATE_TMP);
   586	  if (ret < 0)
   587	    {
   588	      return ret;
   589	    }
   590	
   591	  ret = velapoka_path(destination, sizeof(destination),
   592	                      VELAPOKA_STORAGE_TEMPLATE);
   593	  if (ret < 0)
   594	    {
   595	      return ret;
   596	    }
   597	
   598	  fd = open(temporary, O_WRONLY | O_CREAT | O_TRUNC, 0664);
   599	  if (fd < 0)
   600	    {
   601	      return -errno;
   602	    }
   603	
   604	  ret = velapoka_write_all(fd, header, sizeof(header));
   605	  if (ret == OK)
   606	    {
   607	      ret = velapoka_write_all(fd, reference, VELAPOKA_INSPECT_SIZE);
   608	    }
   609	
   610	  ret = velapoka_sync_close(fd, ret);
   611	  if (ret < 0)
   612	    {
   613	      unlink(temporary);
   614	      return ret;
   615	    }
   616	
   617	  ret = velapoka_replace(temporary, destination);
   618	  if (ret == OK)
   619	    {
   620	      ret = velapoka_storage_write_config(threshold_percent);
   621	    }
   622	
   623	  return ret;
   624	}
