   626	static int velapoka_storage_write_bmp(uint32_t id,
   627	                                      FAR const uint8_t *gray,
   628	                                      FAR char *relative,
   629	                                      size_t relative_size)
   630	{
   631	  uint8_t header[VELAPOKA_BMP_HEADER_SIZE];
   632	  char path[VELAPOKA_STORAGE_PATH_SIZE];
   633	  uint32_t image_size = VELAPOKA_INSPECT_SIZE;
   634	  uint32_t file_size = VELAPOKA_BMP_HEADER_SIZE + image_size;
   635	  unsigned int i;
   636	  int length;
   637	  int fd;
   638	  int ret;
   639	
   640	  length = snprintf(relative, relative_size, "%s/fail_%08" PRIu32 ".bmp",
   641	                    VELAPOKA_STORAGE_FAIL_DIR, id);
