   647	  ret = velapoka_path(path, sizeof(path), relative);
   648	  if (ret < 0)
   649	    {
   650	      return ret;
   651	    }
   652	
   653	  memset(header, 0, sizeof(header));
   654	  header[0] = 'B';
   655	  header[1] = 'M';
   656	  velapoka_put_le32(&header[2], file_size);
   657	  velapoka_put_le32(&header[10], VELAPOKA_BMP_HEADER_SIZE);
   658	  velapoka_put_le32(&header[14], 40);
   659	  velapoka_put_le32(&header[18], VELAPOKA_INSPECT_WIDTH);
   660	  velapoka_put_le32(&header[22], VELAPOKA_INSPECT_HEIGHT);
   661	  velapoka_put_le16(&header[26], 1);
   662	  velapoka_put_le16(&header[28], 8);
