   665	  for (i = 0; i < 256; i++)
   666	    {
   667	      header[54 + i * 4] = i;
   668	      header[55 + i * 4] = i;
   669	      header[56 + i * 4] = i;
   670	    }
   671	
   672	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0664);
   673	  if (fd < 0)
   674	    {
   675	      return -errno;
   676	    }
   677	
   678	  ret = velapoka_write_all(fd, header, sizeof(header));
   679	  for (i = 0; ret == OK && i < VELAPOKA_INSPECT_HEIGHT; i++)
   680	    {
   681	      FAR const uint8_t *row =
