   690	static int velapoka_json_append(FAR char *json, size_t size,
   691	                                FAR size_t *used, FAR const char *format,
   692	                                ...)
   693	{
   694	  va_list args;
   695	  int length;
   696	
   697	  va_start(args, format);
   698	  length = vsnprintf(json + *used, size - *used, format, args);
   699	  va_end(args);
   700	  if (length < 0 || (size_t)length >= size - *used)
   701	    {
   702	      return -EOVERFLOW;
   703	    }
   704	
   705	  *used += length;
   706	  return OK;
   707	}
