  1005	int velapoka_storage_stop(FAR struct velapoka_storage_s *storage)
  1006	{
  1007	  int cleanup_ret;
  1008	  int ret;
  1009	
  1010	  if (storage == NULL)
  1011	    {
  1012	      return OK;
  1013	    }
  1014	
  1015	  pthread_mutex_lock(&storage->lock);
  1016	  storage->stop = true;
  1017	  pthread_cond_signal(&storage->cond);
  1018	  pthread_mutex_unlock(&storage->lock);
  1019	
  1020	  if (storage->thread_started)
  1021	    {
  1022	      pthread_join(storage->thread, NULL);
  1023	    }
  1024	
  1025	  pthread_mutex_lock(&storage->lock);
  1026	  ret = storage->last_error;
  1027	  pthread_mutex_unlock(&storage->lock);
  1028	
  1029	  cleanup_ret = velapoka_storage_cleanup(storage);
  1030	  return ret < 0 ? ret : cleanup_ret;
  1031	}
