  1063	int velapoka_storage_load_reference(
  1064	  FAR struct velapoka_storage_s *storage, FAR uint8_t *reference,
  1065	  size_t size, FAR unsigned int *threshold_percent)
  1066	{
  1067	  uint8_t header[VELAPOKA_STORAGE_HEADER_SIZE];
  1068	  char path[VELAPOKA_STORAGE_PATH_SIZE];
  1069	  int fd;
  1070	  int ret;
  1071	
  1072	  if (storage == NULL || reference == NULL ||
  1073	      size != VELAPOKA_INSPECT_SIZE || threshold_percent == NULL)
  1074	    {
  1075	      return -EINVAL;
  1076	    }
  1077	
  1078	  ret = velapoka_path(path, sizeof(path), VELAPOKA_STORAGE_TEMPLATE);
  1079	  if (ret < 0)
  1080	    {
  1081	      return ret;
  1082	    }
  1083	
  1084	  fd = open(path, O_RDONLY);
  1085	  if (fd < 0)
  1086	    {
  1087	      return -errno;
  1088	    }
