   182	static int velapoka_read_all(int fd, FAR uint8_t *buffer, size_t size)
   183	{
   184	  size_t received = 0;
   185	
   186	  while (received < size)
   187	    {
   188	      ssize_t ret = read(fd, buffer + received, size - received);
   189	
   190	      if (ret < 0)
   191	        {
   192	          if (errno == EINTR)
   193	            {
   194	              continue;
   195	            }
   196	
   197	          return -errno;
   198	        }
   199	
   200	      if (ret == 0)
   201	        {
   202	          return -EIO;
   203	        }
   204	
   205	      received += ret;
   206	    }
   207	
   208	  return OK;
   209	}
