   249	static int velapoka_mkdir_all(FAR const char *path)
   250	{
   251	  char partial[VELAPOKA_STORAGE_PATH_SIZE];
   252	  FAR char *separator;
   253	  size_t length;
   254	  int ret;
   255	
   256	  length = strlen(path);
   257	  if (length == 0 || length >= sizeof(partial) || path[0] != '/')
   258	    {
   259	      return -EINVAL;
   260	    }
   261	
   262	  memcpy(partial, path, length + 1);
   263	  separator = partial + 1;
   264	  while ((separator = strchr(separator, '/')) != NULL)
   265	    {
   266	      *separator = '\0';
   267	      ret = velapoka_mkdir(partial);
   268	      *separator = '/';
   269	      if (ret < 0)
   270	        {
   271	          return ret;
   272	        }
   273	
   274	      separator++;
   275	    }
   276	
   277	  return velapoka_mkdir(partial);
   278	}
