   353	static void velapoka_history_push(
   354	  FAR struct velapoka_storage_s *storage, uint32_t id, bool pass,
   355	  uint16_t score_tenths)
   356	{
   357	  unsigned int move;
   358	
   359	  move = storage->history_count < VELAPOKA_HISTORY_COUNT ?
   360	         storage->history_count : VELAPOKA_HISTORY_COUNT - 1;
   361	  while (move > 0)
   362	    {
   363	      storage->history[move] = storage->history[move - 1];
   364	      move--;
   365	    }
   366	
   367	  storage->history[0].id = id;
   368	  storage->history[0].pass = pass;
   369	  storage->history[0].score_tenths = score_tenths;
   370	  if (storage->history_count < VELAPOKA_HISTORY_COUNT)
   371	    {
   372	      storage->history_count++;
   373	    }
   374	}
