   376	static int velapoka_storage_load_history(
   377	  FAR struct velapoka_storage_s *storage)
   378	{
   379	  char path[VELAPOKA_STORAGE_PATH_SIZE];
   380	  char line[VELAPOKA_STORAGE_JSON_SIZE];
   380	  char line[VELAPOKA_STORAGE_JSON_SIZE];
   381	  FILE *stream;
   382	  unsigned int loaded = 0;
   383	  unsigned int duplicates = 0;
   384	  unsigned int skipped = 0;
   385	  uint32_t previous_id = 0;
   386	  bool have_previous = false;
   387	  int ret;
   388	
   389	  ret = velapoka_path(path, sizeof(path), VELAPOKA_STORAGE_RESULTS);
   390	  if (ret < 0)
   391	    {
   392	      return ret;
   393	    }
   394	
   395	  stream = fopen(path, "r");
   396	  if (stream == NULL)
   397	    {
   398	      return errno == ENOENT ? OK : -errno;
   399	    }
   400	
   401	  while (fgets(line, sizeof(line), stream) != NULL)
   402	    {
   403	      char result[5];
   404	      uint32_t id;
   405	      unsigned int score;
   406	
   407	      if (sscanf(line, "{\"id\":%" SCNu32
   408	                 ",\"frame\":%*u,\"result\":\"%4s\""
   409	                 ",\"score_tenths\":%u", &id, result, &score) == 3)
   410	        {
   411	          if (have_previous && id <= previous_id)
   412	            {
   413	              duplicates++;
   414	              continue;
   415	            }
   416	
   417	          velapoka_history_push(storage, id,
   418	                                strcmp(result, "PASS") == 0,
   419	                                score > UINT16_MAX ? UINT16_MAX : score);
   420	          loaded++;
   421	          previous_id = id;
   422	          have_previous = true;
   423	        }
   424	      else
   425	        {
   426	          skipped++;
   427	        }
   428	    }
   429	
   430	  if (ferror(stream))
   431	    {
   432	      ret = -EIO;
   433	    }
   434	
   435	  if (fclose(stream) != 0 && ret == OK)
   436	    {
   437	      ret = -errno;
   438	    }
   439	
   440	  if (ret == OK && have_previous)
   441	    {
   442	      if (previous_id == UINT32_MAX)
   443	        {
   444	          ret = -EOVERFLOW;
   445	        }
   446	      else
   447	        {
   448	          storage->next_id = previous_id + 1;
   449	        }
   450	    }
   451	
   452	  syslog(LOG_INFO,
   453	         "VelaPoka storage: history loaded=%u duplicates=%u skipped=%u "
   454	         "next=%" PRIu32 "\n",
   455	         loaded, duplicates, skipped, storage->next_id);
   456	  return ret;
   457	}
