+  network = calloc(1, sizeof(*network));
+  if (network == NULL)
+    {
+      return -ENOMEM;
+    }
+
+  ret = pthread_mutex_init(&network->lock, NULL);
+  if (ret != 0)
+    {
+      free(network);
