static int velapoka_network_configure_interface(void)
{
  struct in_addr address;

  address.s_addr = htonl(CONFIG_EXAMPLES_VELAPOKA_NETWORK_IPADDR);
  if (netlib_set_ipv4addr(VELAPOKA_NETWORK_INTERFACE, &address) < 0)
    {
