   107	  address.s_addr = htonl(CONFIG_EXAMPLES_VELAPOKA_NETWORK_IPADDR);
   108	  if (netlib_set_ipv4addr(VELAPOKA_NETWORK_INTERFACE, &address) < 0)
   109	    {
   110	      return velapoka_network_errno();
   111	    }
   112	
   113	  address.s_addr = htonl(CONFIG_EXAMPLES_VELAPOKA_NETWORK_NETMASK);
   114	  if (netlib_set_ipv4netmask(VELAPOKA_NETWORK_INTERFACE, &address) < 0)
   115	    {
   116	      return velapoka_network_errno();
   117	    }
   118	
   119	  address.s_addr = htonl(CONFIG_EXAMPLES_VELAPOKA_NETWORK_ROUTER);
   120	  if (netlib_set_dripv4addr(VELAPOKA_NETWORK_INTERFACE, &address) < 0)
   121	    {
   122	      return velapoka_network_errno();
   123	    }
   124	
   125	  if (netlib_ifup(VELAPOKA_NETWORK_INTERFACE) < 0)
   126	    {
   127	      return velapoka_network_errno();
   128	    }
   129	
   130	  return OK;
   131	}
