   133	static void velapoka_network_format_ip(FAR char *buffer, size_t size)
   134	{
   135	  uint32_t address = CONFIG_EXAMPLES_VELAPOKA_NETWORK_IPADDR;
   136	
   137	  snprintf(buffer, size, "%" PRIu32 ".%" PRIu32 ".%" PRIu32 ".%" PRIu32,
   138	           (address >> 24) & 0xff, (address >> 16) & 0xff,
   139	           (address >> 8) & 0xff, address & 0xff);
   140	}
