   142	static int velapoka_network_send_all(int fd, FAR const void *data,
   143	                                     size_t size)
   144	{
   145	  FAR const uint8_t *buffer = data;
   146	  size_t sent = 0;
   147	
   148	  while (sent < size)
   149	    {
   150	      ssize_t ret = send(fd, buffer + sent, size - sent, MSG_NOSIGNAL);
   151	
   152	      if (ret < 0)
   153	        {
   154	          if (errno == EINTR)
   155	            {
   156	              continue;
   157	            }
   158	
   159	          return -errno;
   160	        }
   161	
   162	      if (ret == 0)
   163	        {
   164	          return -EPIPE;
   165	        }
   166	
   167	      sent += ret;
   168	    }
   169	
   170	  return OK;
   171	}
