   173	static int velapoka_network_send_response(
   174	  int fd, int status, FAR const char *reason, FAR const char *content_type,
   175	  FAR const void *body, size_t body_size)
   176	{
   177	  char header[VELAPOKA_NETWORK_HEADER_SIZE];
   178	  int length;
   179	  int ret;
   180	
   181	  length = snprintf(header, sizeof(header),
   182	                    "HTTP/1.1 %d %s\r\n"
   183	                    "Server: VelaPoka\r\n"
   184	                    "Content-Type: %s\r\n"
   185	                    "Content-Length: %zu\r\n"
   186	                    "Cache-Control: no-store\r\n"
   187	                    "Access-Control-Allow-Origin: *\r\n"
   188	                    "Connection: close\r\n\r\n",
   189	                    status, reason, content_type, body_size);
   190	  if (length <= 0 || (size_t)length >= sizeof(header))
   191	    {
   192	      return -EOVERFLOW;
   193	    }
   194	
   195	  ret = velapoka_network_send_all(fd, header, length);
   196	  if (ret == OK && body_size > 0)
   197	    {
   198	      ret = velapoka_network_send_all(fd, body, body_size);
   199	    }
   200	
   201	  return ret;
   202	}
