   311	static int velapoka_network_parse_path(FAR char *request, size_t size,
   312	                                       FAR char **path)
   313	{
   314	  FAR char *end;
   315	  FAR char *query;
   316	
   317	  request[size] = '\0';
   318	  if (strncmp(request, "GET ", 4) != 0)
   319	    {
   320	      return -ENOTSUP;
   321	    }
   322	
   323	  *path = request + 4;
   324	  end = strchr(*path, ' ');
   325	  if (end == NULL || end == *path)
   326	    {
   327	      return -EBADMSG;
   328	    }
   329	
   330	  *end = '\0';
   331	  query = strchr(*path, '?');
   332	  if (query != NULL)
   333	    {
   334	      *query = '\0';
   335	    }
   336	
   337	  return OK;
   338	}
   339	
   340	static int velapoka_network_read_request(int fd, FAR char *request,
   341	                                         size_t capacity,
   342	                                         FAR size_t *request_size)
   343	{
   344	  size_t used = 0;
   345	
   346	  while (used < capacity)
   347	    {
   348	      ssize_t ret = recv(fd, request + used, capacity - used, 0);
   349	
   350	      if (ret < 0)
   351	        {
   352	          if (errno == EINTR)
   353	            {
   354	              continue;
   355	            }
   356	
   357	          return -errno;
   358	        }
   359	
   360	      if (ret == 0)
   361	        {
   362	          break;
   363	        }
   364	
   365	      used += ret;
   366	      if ((used >= 4 && strstr(request, "\r\n\r\n") != NULL) ||
   367	          (used >= 2 && strstr(request, "\n\n") != NULL))
   368	        {
   369	          break;
   370	        }
   371	    }
   372	
   373	  *request_size = used;
   374	  return used > 0 ? OK : -ECONNRESET;
   375	}
