   377	static int velapoka_network_handle_client(
   378	  FAR struct velapoka_network_s *network, int fd)
   379	{
   380	  char request[VELAPOKA_NETWORK_REQUEST_SIZE + 1];
   381	  FAR char *path;
   382	  size_t request_size = 0;
   383	  int ret;
   384	
   385	  memset(request, 0, sizeof(request));
   386	  ret = velapoka_network_read_request(fd, request,
   387	                                      VELAPOKA_NETWORK_REQUEST_SIZE,
   388	                                      &request_size);
   389	  if (ret < 0)
   390	    {
   391	      return ret;
   392	    }
   393	
   394	  ret = velapoka_network_parse_path(request, request_size, &path);
   395	  if (ret == -ENOTSUP)
   396	    {
   397	      return velapoka_network_send_error(fd, 405, "Method Not Allowed",
   398	                                         "only GET is supported");
   399	    }
   400	  else if (ret < 0)
   401	    {
   402	      return velapoka_network_send_error(fd, 400, "Bad Request",
   403	                                         "invalid HTTP request");
   404	    }
   405	
   406	  if (strcmp(path, "/") == 0)
   407	    {
   408	      static const char body[] =
   409	        "{\"service\":\"VelaPoka\",\"endpoints\":["
   410	        "\"/api/status\",\"/api/results\","
   411	        "\"/files/fail/fail_XXXXXXXX.bmp\"]}\n";
   412	
   413	      return velapoka_network_send_response(fd, 200, "OK",
   414	                                            "application/json", body,
   415	                                            sizeof(body) - 1);
   416	    }
   417	
   418	  if (strcmp(path, "/api/status") == 0)
   419	    {
   420	      return velapoka_network_send_status(network, fd);
   421	    }
   422	
   423	  if (strcmp(path, "/api/results") == 0)
   424	    {
   425	      return velapoka_network_send_export(network, fd, "results.jsonl",
   426	                                          "application/x-ndjson");
   427	    }
   428	
   429	  if (strncmp(path, "/files/", 7) == 0)
   430	    {
   431	      return velapoka_network_send_export(network, fd, path + 7,
   432	                                          "image/bmp");
   433	    }
   434	
   435	  return velapoka_network_send_error(fd, 404, "Not Found",
   436	                                     "endpoint not found");
   437	}
