   439	static FAR void *velapoka_network_thread(FAR void *arg)
   440	{
   441	  FAR struct velapoka_network_s *network = arg;
   442	  struct sockaddr_in address;
   443	  struct pollfd descriptor;
   444	  char ip[INET_ADDRSTRLEN];
   445	  int listen_fd;
   446	  int option = 1;
   447	  int ret;
   448	
   449	  ret = velapoka_network_configure_interface();
   450	  if (ret < 0)
   451	    {
   452	      fprintf(stderr, "VelaPoka network: %s setup failed: %d\n",
   453	              VELAPOKA_NETWORK_INTERFACE, ret);
   454	      velapoka_network_set_result(network, false, ret);
   455	      return NULL;
   456	    }
   457	
   458	  listen_fd = socket(AF_INET, SOCK_STREAM, 0);
   459	  if (listen_fd < 0)
   460	    {
   461	      ret = -errno;
   462	      goto out;
   463	    }
   464	
   465	  setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &option, sizeof(option));
   466	  memset(&address, 0, sizeof(address));
   467	  address.sin_family = AF_INET;
   468	  address.sin_port = htons(CONFIG_EXAMPLES_VELAPOKA_NETWORK_PORT);
   469	  address.sin_addr.s_addr = htonl(INADDR_ANY);
   470	  if (bind(listen_fd, (FAR struct sockaddr *)&address,
   471	           sizeof(address)) < 0)
   472	    {
   473	      ret = -errno;
   474	      close(listen_fd);
   475	      goto out;
   476	    }
   477	
   478	  if (listen(listen_fd, VELAPOKA_NETWORK_BACKLOG) < 0)
   479	    {
   480	      ret = -errno;
   481	      close(listen_fd);
   482	      goto out;
   483	    }
   484	
   485	  velapoka_network_set_result(network, true, OK);
   486	  velapoka_network_format_ip(ip, sizeof(ip));
   487	  printf("VelaPoka network: http://%s:%u ready on %s\n", ip,
   488	         CONFIG_EXAMPLES_VELAPOKA_NETWORK_PORT,
   489	         VELAPOKA_NETWORK_INTERFACE);
   490	
   491	  descriptor.fd = listen_fd;
   492	  descriptor.events = POLLIN;
   493	  while (!velapoka_network_should_stop(network))
   494	    {
   495	      descriptor.revents = 0;
   496	      ret = poll(&descriptor, 1, VELAPOKA_NETWORK_POLL_TIMEOUT_MS);
   497	      if (ret < 0)
   498	        {
   499	          if (errno == EINTR)
   500	            {
   501	              continue;
   502	            }
   503	
   504	          ret = -errno;
   505	          break;
   506	        }
   507	
   508	      if (ret > 0 && (descriptor.revents & POLLIN) != 0)
   509	        {
   510	          struct timeval timeout;
   511	          int client_fd = accept(listen_fd, NULL, NULL);
   512	
   513	          if (client_fd < 0)
   514	            {
   515	              if (errno == EINTR)
   516	                {
   517	                  continue;
   518	                }
   519	
   520	              ret = -errno;
   521	              break;
   522	            }
   523	
   524	          timeout.tv_sec = VELAPOKA_NETWORK_IO_TIMEOUT_SEC;
   525	          timeout.tv_usec = 0;
   526	          setsockopt(client_fd, SOL_SOCKET, SO_RCVTIMEO,
   527	                     &timeout, sizeof(timeout));
   528	          setsockopt(client_fd, SOL_SOCKET, SO_SNDTIMEO,
   529	                     &timeout, sizeof(timeout));
   530	          velapoka_network_handle_client(network, client_fd);
   531	          close(client_fd);
   532	        }
   533	      else if (ret > 0 &&
   534	               (descriptor.revents & (POLLERR | POLLHUP | POLLNVAL)) != 0)
   535	        {
   536	          ret = -EIO;
   537	          break;
   538	        }
   539	    }
   540	
   541	  close(listen_fd);
   542	  if (velapoka_network_should_stop(network))
   543	    {
   544	      ret = OK;
   545	    }
   546	
   547	out:
   548	  velapoka_network_set_result(network, false, ret);
   549	  if (ret < 0)
   550	    {
   551	      fprintf(stderr, "VelaPoka network: server stopped: %d\n", ret);
   552	    }
   553	
   554	  return NULL;
   555	}
