   822	static FAR void *velapoka_storage_thread(FAR void *arg)
   823	{
   824	  FAR struct velapoka_storage_s *storage = arg;
   825	
   826	  for (; ; )
   827	    {
   828	      FAR struct velapoka_storage_request_s *request = NULL;
   829	      unsigned int threshold = 0;
   830	      bool save_reference = false;
   831	      bool save_result = false;
   832	      int ret;
   833	
   834	      pthread_mutex_lock(&storage->lock);
   835	      while (!storage->reference_pending && storage->request_count == 0 &&
   836	             !storage->stop)
   837	        {
   838	          pthread_cond_wait(&storage->cond, &storage->lock);
   839	        }
   840	
   841	      if (storage->stop && !storage->reference_pending &&
   842	          storage->request_count == 0)
   843	        {
   844	          pthread_mutex_unlock(&storage->lock);
   845	          break;
   846	        }
   847	
   848	      if (storage->reference_pending)
   849	        {
   850	          storage->reference_pending = false;
   851	          storage->reference_busy = true;
   852	          threshold = storage->reference_threshold;
   853	          save_reference = true;
   854	        }
   855	      else if (storage->request_count > 0)
   856	        {
   857	          request = &storage->requests[storage->request_head];
   858	          save_result = true;
   859	        }
   860	
   861	      pthread_mutex_unlock(&storage->lock);
   862	
   863	      pthread_mutex_lock(&storage->io_lock);
   864	      if (save_reference)
   865	        {
   866	          ret = velapoka_storage_write_reference(storage->reference,
   867	                                                 threshold);
   868	        }
   869	      else if (save_result)
   870	        {
   871	          ret = velapoka_storage_write_result(
   872	            request->id, &request->result, request->image,
   873	            request->has_image, request->threshold);
   874	        }
   875	      else
   876	        {
   877	          ret = OK;
   878	        }
   879	
   880	      pthread_mutex_unlock(&storage->io_lock);
   881	
   882	      if (ret < 0)
   883	        {
   884	          velapoka_storage_set_error(storage, ret);
   885	        }
   886	
   887	      pthread_mutex_lock(&storage->lock);
   888	      if (save_reference)
   889	        {
   890	          storage->reference_busy = false;
   891	        }
   892	
   893	      if (save_result)
   894	        {
   895	          storage->request_head =
   896	            (storage->request_head + 1) % VELAPOKA_STORAGE_QUEUE_DEPTH;
   897	          storage->request_count--;
   898	        }
   899	
   900	      pthread_mutex_unlock(&storage->lock);
   901	    }
   902	
   903	  return NULL;
   904	}
