   906	static int velapoka_storage_cleanup(
   907	  FAR struct velapoka_storage_s *storage)
   908	{
   909	  unsigned int i;
   910	  int ret = OK;
   911	
   912	  for (i = 0; i < VELAPOKA_STORAGE_QUEUE_DEPTH; i++)
   913	    {
   914	      free(storage->requests[i].image);
   915	    }
   916	
   917	  free(storage->reference);
   918	  if (storage->mounted_here &&
   919	      umount(CONFIG_EXAMPLES_VELAPOKA_STORAGE_MOUNTPOINT) < 0)
   920	    {
